-- База на Ташкентской: частичная панорама 180° (контора, «слишком чисто») и предметы «есть, но не улика»
begin;
update locations set image_url = 'https://zhdvfvrqgunjickiaoqi.supabase.co/storage/v1/object/public/location-images/v2-baza-wide.jpg', pano_haov = 180, search_note = 'Осмотр ничего не дал. Слишком чисто для конторы, где идёт торговля: пол вымыт, корзины пустые, на столах ни бумажки. Тут прибрались до вас. Спрашивайте людей.' where id = '92cac3d9-0cc0-5a14-b4bc-91a65f6e04ed';
delete from case_decoy_categories where location_id = '92cac3d9-0cc0-5a14-b4bc-91a65f6e04ed';
commit;
select (select count(*) from case_decoy_categories where location_id = '92cac3d9-0cc0-5a14-b4bc-91a65f6e04ed') decoys, (select pano_haov from locations where id = '92cac3d9-0cc0-5a14-b4bc-91a65f6e04ed') haov, (select left(search_note, 40) from locations where id = '92cac3d9-0cc0-5a14-b4bc-91a65f6e04ed') note;
